import org.eclipse.swt.custom.StyledText;
import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.Rectangle;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;

public class DrawingExample {
    public void draw(StyledText textWidget, GC gc) {
        gc.setBackground(textWidget.getBackground());
        Rectangle client = textWidget.getClientArea();
        int y = 5;
        // Transformed code
        gc.fillRectangle(0, y, client.width, 20);
    }

    // Minimal setup for StyledText and GC context
    public static void main(String[] args) {
        Display display = new Display();
        Shell shell = new Shell(display);
        StyledText styledText = new StyledText(shell, SWT.NONE);
        GC gc = new GC(styledText);
        DrawingExample example = new DrawingExample();
        example.draw(styledText, gc);
        gc.dispose();
        shell.dispose();
        display.dispose();
    }
}

