import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.Rectangle;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;

class CustomWidget {
    // A custom widget with a similar method, but not StyledText
    public void drawBackground(GC gc, int x, int y, int width, int height) {
        System.out.println("CustomWidget drawing background");
    }
}

public class DrawingExampleNegative {
    public void draw(CustomWidget myWidget, GC gc) {
        // Should not match as myWidget is not org.eclipse.swt.custom.StyledText
        myWidget.drawBackground(gc, 0, 0, 100, 50);
    }

    public void drawWithWrongGC(StyledText textWidget, Object other) {
        // Should not match as 'other' is not org.eclipse.swt.graphics.GC
        // textWidget.drawBackground(other, 0, 0, 100, 50);
    }

    public static void main(String[] args) {
        Display display = new Display();
        Shell shell = new Shell(display);
        StyledText styledText = new StyledText(shell, SWT.NONE);
        GC gc = new GC(styledText);
        new DrawingExampleNegative().draw(new CustomWidget(), gc);
        new DrawingExampleNegative().drawWithWrongGC(styledText, new Object());
        gc.dispose();
        shell.dispose();
        display.dispose();
    }
}
